<?php $title='Edit Post';require __DIR__.'/_layout.php';if(!can_manage('posts'))exit('Forbidden');$id=(int)($_GET['id']??0);$st=db()->prepare("SELECT * FROM posts WHERE id=?");$st->execute([$id]);$p=$st->fetch();if(!$p)exit('Not found');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$slug=unique_slug(slugify($_POST['slug']?:$_POST['title']),$id);$st=db()->prepare("UPDATE posts SET title=?,slug=?,excerpt=?,content=?,category_id=?,status=?,published_at=?,seo_title=?,seo_description=?,updated_at=NOW() WHERE id=?");$st->execute([trim($_POST['title']),$slug,trim($_POST['excerpt']),$_POST['content'],(int)($_POST['category_id']?:0),$_POST['status'],$_POST['published_at']?:date('Y-m-d H:i:s'),trim($_POST['seo_title']),trim($_POST['seo_description']),$id]);log_activity(current_user()['id'],'updated','post',$id);flash('success','Post updated.');redirect('posts.php');}?><h1>Edit Post</h1><?php include __DIR__.'/_post_form.php';require __DIR__.'/_footer.php';